#[cfg(feature = "trace")]
impl B {
    /// The Bend branch, as `module:def:pattern`.
    pub(crate) fn label(self) -> &'static str {
        LABELS.iter().find(|(b, _)| *b == self).map_or("", |(_, label)| label)
    }
}
